function Toggle({label,value,onChange}){return <label className="toggle"><span>{label}</span><input type="checkbox" checked={value} onChange={e=>onChange(e.target.checked)}/><i/></label>}
function ScenePreview({config}){const host=useRef();useEffect(()=>{let renderer,scene,camera,control,grid,model,mixer,frame,previewModel=null;const root=host.current;renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor(0x000000,0);root.append(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(45,1,.1,100);camera.position.set(4.2,3.2,5.2);control=new OrbitControls(camera,renderer.domElement);control.enableDamping=true;control.dampingFactor=.08;control.target.set(0,.9,0);const hemi=new THREE.HemisphereLight(0x88bbff,0x1a2a4a,.85),sun=new THREE.DirectionalLight(0xe8f0ff,1.4),rim=new THREE.PointLight(0x88aaff,.8,40);sun.position.set(-4,7,5);sun.castShadow=true;sun.shadow.camera.left=-6;sun.shadow.camera.right=6;sun.shadow.camera.top=6;sun.shadow.camera.bottom=-6;sun.shadow.camera.near=.5;sun.shadow.camera.far=30;rim.position.set(5,3,-4);scene.add(hemi,sun,rim);grid=new THREE.GridHelper(12,12,0x2a5a9a,0x1a3058);grid.position.y=0;scene.add(grid);const ground=new THREE.Mesh(new THREE.PlaneGeometry(30,30),new THREE.ShadowMaterial({opacity:.22}));ground.rotation.x=-Math.PI/2;ground.position.y=-.01;ground.receiveShadow=true;scene.add(ground);const fit=obj=>{const bounds=new THREE.Box3().setFromObject(obj),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3()),f=THREE.MathUtils.degToRad(camera.fov),distance=Math.max(size.y/(2*Math.tan(f/2)),size.x/(2*Math.tan(f/2)*camera.aspect),size.z*.6)*1.6;control.target.copy(center);camera.position.copy(center).addScaledVector(new THREE.Vector3(.72,.52,.78).normalize(),distance);camera.near=Math.max(.01,distance/1200);camera.far=Math.max(1000,distance*80);camera.updateProjectionMatrix();control.minDistance=Math.max(.1,distance*.12);control.maxDistance=Math.max(40,distance*5);grid.scale.setScalar(Math.max(1,Math.max(size.x,size.y,size.z)/12*1.25));grid.position.set(center.x,bounds.min.y-.04,center.z);control.update()};const disposeModel=m=>{if(!m)return;m.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(mm=>mm.dispose())})};const loadDefault=()=>{if(previewModel){disposeModel(previewModel);scene.remove(previewModel)}const g=createFactoryModel();previewModel=g;scene.add(g);fit(g)};const loadModelFile=async name=>{try{const {object,mixer:m}=await loadModelByName(name);mixer=m;if(previewModel){disposeModel(previewModel);scene.remove(previewModel)}previewModel=object;scene.add(object);fit(object)}catch{loadDefault()}};loadDefault();const activeModel=localStorage.getItem('factory-active-model');if(activeModel&&activeModel!=='__factory_default__'&&activeModel!=='Factory Campus A.glb'){loadModelFile(activeModel)}const onModelChange=e=>{const name=e.detail;if(!name||name==='__factory_default__'||name==='Factory Campus A.glb'){mixer=null;loadDefault()}else{loadModelFile(name)}};window.addEventListener('factory-active-model-change',onModelChange);const resize=()=>{const r=root.getBoundingClientRect();if(r.width<10||r.height<10)return;renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()};const obs=new ResizeObserver(resize);obs.observe(root);setTimeout(resize,50);const loop=()=>{mixer?.update(.016);control.update();renderer.render(scene,camera);frame=requestAnimationFrame(loop)};loop();root._pw={renderer,scene,camera,control,grid,hemi,sun,rim,model:previewModel,cleanup:()=>{cancelAnimationFrame(frame);obs.disconnect();window.removeEventListener('factory-active-model-change',onModelChange);disposeModel(previewModel);renderer.dispose();root.replaceChildren()}};return()=>root._pw?.cleanup()},[]);useEffect(()=>{const p=host.current?._pw;if(!p)return;const env={factory:[0x000000,0xa6c8ff,0x071128,2.2,0xd8e8ff,3,0x4488ff,22],studio:[0x172440,0xffffff,0x4b5561,3.1,0xffffff,3.8,0x9fc0ff,13],dusk:[0x251625,0x8b87c9,0x241625,1.9,0xffa96d,3.3,0xe266b8,18]}[config.scene.environment];p.hemi.color.setHex(env[1]);p.hemi.groundColor.setHex(env[2]);p.hemi.intensity=env[3]*config.scene.ambientIntensity;p.sun.color.setHex(env[4]);p.sun.intensity=env[5]*config.scene.sunIntensity;p.sun.shadow.radius=config.scene.shadowSoftness;p.rim.color.setHex(env[6]);p.rim.intensity=env[7];p.camera.fov=config.scene.fov;p.camera.updateProjectionMatrix();p.control.enableRotate=config.scene.rotate;p.control.enableZoom=config.scene.zoom;p.control.enablePan=config.scene.pan;p.control.autoRotate=config.scene.display!=='static';p.control.autoRotateSpeed=config.scene.rotationSpeed*(config.scene.display==='showcase'?1.65:1);p.grid.visible=config.scene.grid;p.renderer.shadowMap.enabled=config.scene.shadows;const ss={low:512,medium:1024,high:2048}[config.scene.shadowQuality]||1024;p.sun.shadow.mapSize.set(ss,ss);p.sun.shadow.needsUpdate=true;p.renderer.toneMappingExposure=config.scene.exposure;p.renderer.setPixelRatio(config.scene.dpr==='auto'?Math.min(devicePixelRatio,2):Number(config.scene.dpr));if(config.scene.sunManual){const az=config.scene.sunAzimuth*Math.PI/180,el=config.scene.sunElevation*Math.PI/180,r=18;p.sun.position.set(Math.cos(el)*Math.sin(az)*r,Math.sin(el)*r,Math.cos(el)*Math.cos(az)*r)}},[config.scene]);return <div className="scene-preview" ref={host}><div className="preview-badge">实时预览</div><div className="preview-hint">拖动旋转 · 滚轮缩放</div></div>}
function Settings(){const {config,setConfig,t}=useApp(),[tab,setTab]=useState('scene');const changeScene=patch=>setConfig(x=>({...x,scene:{...x.scene,...patch}}));const tabs=[['general',t.general],['brand',t.brand],['nav',t.nav],['scene',t.scene],['system',t.system]];return <div className="settings"><nav>{tabs.map(x=><button className={tab===x[0]?'active':''} onClick={()=>setTab(x[0])} key={x[0]}>{x[1]}<ChevronRight size={15}/></button>)}</nav><Card title={tabs.find(x=>x[0]===tab)[1]}>{tab==='general'&&<div className="form"><label>默认语言<select value={config.language} onChange={e=>setConfig(x=>({...x,language:e.target.value}))}><option value="zh">简体中文</option><option value="en">English</option></select></label></div>}{tab==='brand'&&<div className="form"><label>应用名称<input value={config.branding.title} onChange={e=>setConfig(x=>({...x,branding:{...x.branding,title:e.target.value}}))}/></label><label>主题<div className="choice"><button className={config.theme==='dark'?'active':''} onClick={()=>setConfig(x=>({...x,theme:'dark'}))}><Moon/>深色</button><button className={config.theme==='light'?'active':''} onClick={()=>setConfig(x=>({...x,theme:'light'}))}><Sun/>浅色</button></div></label></div>}{tab==='nav'&&<div className="form"><label>导航模式<div className="choice">{['open','mini','overlay'].map(x=><button key={x} className={config.nav===x?'active':''} onClick={()=>setConfig(v=>({...v,nav:x}))}>{x}</button>)}</div></label><p>展开：固定文字导航；Mini：图标导航；Overlay：悬停展开且不压缩工作区。</p></div>}{tab==='scene'&&<div className="scene-settings-layout"><div className="form scene-form"><label>{t.display}<div className="choice">{['standard','showcase','static'].map(x=><button key={x} className={config.scene.display===x?'active':''} onClick={()=>changeScene({display:x})}>{t[x]}</button>)}</div></label><label>{t.environment}<select value={config.scene.environment} onChange={e=>changeScene({environment:e.target.value})}>{['factory','studio','dusk'].map(x=><option value={x} key={x}>{t[x]}</option>)}</select></label><label>{t.render}<div className="choice">{['low','balanced','quality'].map(x=><button key={x} className={config.scene.preset===x?'active':''} onClick={()=>changeScene({preset:x,dpr:x==='low'?'1':x==='quality'?'2':'auto',shadows:x!=='low'})}>{t[x]}</button>)}</div></label><label>{t.dpr}<select value={config.scene.dpr} onChange={e=>changeScene({dpr:e.target.value})}><option value="auto">{t.auto} (≤ 2×)</option><option value="1">1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label><label>{t.fov}<input type="range" min="25" max="70" value={config.scene.fov} onChange={e=>changeScene({fov:+e.target.value})}/><output>{config.scene.fov}°</output></label><label>{t.speed}<input type="range" min=".1" max="1" step=".1" value={config.scene.rotationSpeed} onChange={e=>changeScene({rotationSpeed:+e.target.value})}/><output>{config.scene.rotationSpeed.toFixed(1)}</output></label><label>{t.exposure}<input type="range" min=".4" max="1.8" step=".1" value={config.scene.exposure} onChange={e=>changeScene({exposure:+e.target.value})}/><output>{config.scene.exposure.toFixed(1)}</output></label><label>{t.ambient}<input type="range" min="0" max="2" step=".1" value={config.scene.ambientIntensity} onChange={e=>changeScene({ambientIntensity:+e.target.value})}/><output>{config.scene.ambientIntensity.toFixed(1)}</output></label><label>{t.sunlight}<input type="range" min="0" max="2" step=".1" value={config.scene.sunIntensity} onChange={e=>changeScene({sunIntensity:+e.target.value})}/><output>{config.scene.sunIntensity.toFixed(1)}</output></label><SunControl config={config} onChange={patch=>changeScene(patch)}/><label>{t.shadowSoftness}<input type="range" min="0" max="8" step=".5" value={config.scene.shadowSoftness} onChange={e=>changeScene({shadowSoftness:+e.target.value})}/><output>{config.scene.shadowSoftness.toFixed(1)}</output></label><label>{t.shadowQuality}<select value={config.scene.shadowQuality} onChange={e=>changeScene({shadowQuality:e.target.value})}>{['low','medium','high'].map(x=><option value={x} key={x}>{t[`shadow${x[0].toUpperCase()}${x.slice(1)}`]}</option>)}</select></label><div className="toggle-grid"><Toggle label={t.rotate} value={config.scene.rotate} onChange={rotate=>changeScene({rotate})}/><Toggle label={t.zoom} value={config.scene.zoom} onChange={zoom=>changeScene({zoom})}/><Toggle label={t.pan} value={config.scene.pan} onChange={pan=>changeScene({pan})}/><Toggle label={t.grid} value={config.scene.grid} onChange={grid=>changeScene({grid})}/><Toggle label={t.shadows} value={config.scene.shadows} onChange={shadows=>changeScene({shadows})}/><Toggle label={t.sunCycle} value={config.scene.sunCycle!==false} onChange={sunCycle=>changeScene({sunCycle})}/></div><div className="online-scene-setting"><b>{t.onlineScene}</b><label>{t.onlineSceneUrl}<input value={config.onlineScene?.url||''} onChange={e=>setConfig(x=>({...x,onlineScene:{...x.onlineScene,url:e.target.value}}))} placeholder="https://my.spline.design/..."/></label><p>{t.onlineSceneHint}</p></div><div className="online-scene-setting"><b>{t.carousel}</b><div className="toggle-grid" style={{gridTemplateColumns:"1fr"}}><Toggle label={t.carouselEnable} value={config.carousel?.enabled||false} onChange={enabled=>setConfig(x=>({...x,carousel:{...x.carousel,enabled}}))}/></div><label>{t.carouselInterval}<input type="range" min="3" max="30" value={config.carousel?.interval||8} onChange={e=>setConfig(x=>({...x,carousel:{...x.carousel,interval:+e.target.value}}))}/><output>{config.carousel?.interval||8}s</output></label><label>{t.carouselModels}<div style={{display:"grid",gap:"6px",maxHeight:"180px",overflow:"auto"}}>{[{name:'Factory Campus A.glb',default:true},...(config.models||[])].map(m=><label key={m.name} style={{display:"flex",gap:"8px",alignItems:"center",fontSize:"12px",color:"var(--muted)"}}><input type="checkbox" checked={(config.carousel?.modelNames||[]).includes(m.name)} onChange={e=>{const names=config.carousel?.modelNames||[];setConfig(x=>({...x,carousel:{...x.carousel,modelNames:e.target.checked?[...names,m.name]:names.filter(n=>n!==m.name)}}))}}/>{m.name.replace(/\.(glb|gltf|fbx|obj|stl)$/i,'')}</label>)}</div></label></div></div><ScenePreview config={config}/></div>}{tab==='system'&&<div className="system-panel"><div className="data-note"><BarChart3 size={36}/><h3>前端演示数据</h3><p>产能、人员、场地及组织关系来自可替换的本地模拟数据服务，后续可由 MES、IoT、HR 接口替换。</p></div><div className="config-actions"><h3>配置管理</h3><div className="config-buttons"><button className="secondary" onClick={()=>{const blob=new Blob([JSON.stringify(config,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='factory-config.json';a.click();URL.revokeObjectURL(a.href)}}>导出配置</button><label className="secondary config-import"><input type="file" accept=".json" onChange={e=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data.version&&data.scene){setConfig({...defaults,...data,version:4});alert('配置已导入')}else alert('配置文件格式不正确')}catch{alert('配置文件解析失败')}};reader.readAsText(f);e.target.value=''}}/>导入配置</label></div><p className="config-hint">导出文件包含场景设置、品牌配置、导航偏好和模型列表。导入将覆盖当前配置。</p></div><div className="storage-info"><h3>本地存储</h3><div className="storage-grid"><div><b>{(new Blob([localStorage.getItem(STORE)||'']).size/1024).toFixed(1)} KB</b><small>配置数据</small></div><div><b>{config.models?.length||0}</b><small>已登记模型</small></div><div><b>{config.language==='zh'?'中文':'English'}</b><small>当前语言</small></div></div></div></div>}<div className="settings-actions"><button className="danger" onClick={()=>setConfig(defaults)}>{t.restore}</button></div></Card></div>}
createRoot(document.querySelector('#app')).render(<ErrorBoundary><Provider><BrowserRouter><Shell/></BrowserRouter></Provider></ErrorBoundary>);
